/**
 * The rules fixtures the kit ships (PRO-123; FRW-020; 12 §5). The published set is generated by the
 * rules package (`packages/rules/scripts/generate.ts`) into `spec/rules/`; the kit keeps a copy in
 * `packages/tck/fixtures/rules/` so that a native backend can run the cases from the kit alone. The
 * copy is written by the kit's `generate` script (`scripts/rules-copy.ts`), never by hand, and its
 * format is described in `packages/tck/fixtures/rules/README.md`.
 *
 * The rule of FRW-020 (no changed expected result and no removed case under the same rules version)
 * is enforced where the fixtures are generated: the rules package's `generate` refuses to write
 * (`changedUnderSameVersion` in `packages/rules/src/artifacts.ts`). The kit adds only the check that
 * its copy equals the published set.
 */
import { createHash } from 'node:crypto';
import { existsSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { kitFixture } from './fixtures.ts';

/** The files the rules package publishes and the kit ships, by name. */
export const RULES_FILES = [
  'rules-1.schema.json',
  'rules-1.fixtures.json',
  'rules-1.manifest.json',
] as const;

export interface RulesManifest {
  rules: string;
  status: string;
  profile: string;
  feature: string;
  generator: string;
  decision: string;
  cases: number;
  files: Record<string, string>;
}

export interface RulesCase {
  id: string;
  category: string;
  expect: unknown;
  [member: string]: unknown;
}

export interface RulesFixtures {
  rules: string;
  status: string;
  presets: Record<string, string>;
  limits: Record<string, number>;
  cases: RulesCase[];
}

/** The kit's copy of the fixtures (`rules/rules-1.fixtures.json`). */
export function rulesFixtures(): RulesFixtures {
  return kitFixture<RulesFixtures>('rules/rules-1.fixtures.json');
}

/** The kit's copy of the manifest (`rules/rules-1.manifest.json`). */
export function rulesManifest(): RulesManifest {
  return kitFixture<RulesManifest>('rules/rules-1.manifest.json');
}

/** The file the rules package publishes for `name`, at the repository root (`spec/rules/`). */
export function publishedRulesFile(name: string): URL {
  return new URL(`../../../spec/rules/${name}`, import.meta.url);
}

/** Whether the repository's published set is present (it is not in the kit's container image). */
export function publishedRulesPresent(): boolean {
  return existsSync(fileURLToPath(publishedRulesFile('rules-1.manifest.json')));
}

export function sha256Hex(text: string | Uint8Array): string {
  return createHash('sha256').update(text).digest('hex');
}
